// livy: generated by livy install; livy uninstall removes this file. Do not edit.
// Records this machine's Amp threads in Livy's ledger. Each handler copies a few fields of
// the event (never a prompt, reply, tool input or tool output; of a skill call, only the skill's
// name and the folder Amp loaded it from), queues them and returns at
// once; `livy amp <event>` writes the line, run in the thread's folder, which decides scope and
// branch. A child that cannot run is recorded here, as a ledger.error in Livy's spill/ folder,
// which the upload ships.
import type { PluginAPI } from '@ampcode/plugin'
import { spawn } from 'node:child_process'
import { mkdirSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const LIVY = __LIVY_BIN__
const DATA = __LIVY_DATA__
const TEMPLATE = __LIVY_TEMPLATE__
const MAX_QUEUE = 1000
const IN_FLIGHT = 4
const CHILD_MS = 10_000
const IDLE_MS = 6 * 60_000
// An orb pauses 5 minutes after the agent's last work, so its last upload must start sooner,
// and unthrottled: no later trigger runs until the orb wakes.
const ORB_IDLE_MS = 3 * 60_000
const PR_CREATE = /\bgh\b[\s\S]*\bpr\b[\s\S]*\bcreate\b/
// The line Amp appends to a loaded skill's text, naming the folder it loaded from.
const SKILL_DIR = /^Base directory for this skill: (file:\/\/\S+)$/gm
const HELD_PER_THREAD = 200
const THREADS = 100
// The crash marker: written here at load and removed at unload, in this process, so a `livy amp
// loaded` child still running at unload cannot write it back after the removal.
const MARKER = `${DATA}/amp-plugin/${process.pid}.alive`

type Job = { event: string; facts: unknown; flush?: boolean; cwd?: string }
const queue: Job[] = []
const counts = { dropped: 0, handler_errors: 0, spill_failed: 0, no_folder: 0 }
let running = 0
let spills = 0
let idle: ReturnType<typeof setTimeout> | undefined
let inOrb = process.env.AMP_ORB === '1'
// The plugin runs in its own folder, not the thread's. A thread's folder is the workspace root
// when Amp has one, else the folder its first shell command ran in. Until one is known, the
// thread's events wait here, and are counted as not recorded if none ever is.
let root: string | null = null
const folders = new Map<string, string>()
const held = new Map<string, Job[]>()

const ts = () => new Date().toISOString().slice(0, 19) + '+00:00'

// spill writes one ledger.error straight into spill/. The plugin cannot tell whether a thread is
// in scope, so the line names no thread or repo; its sequence number keeps two failures in one
// second apart, since identical lines would ship as one object.
function spill(reason: string): void {
  try {
    const dir = `${DATA}/spill`
    const name = `${Date.now()}000000-amp-${process.pid}-${++spills}`
    const line = { schema_version: 1, ts: ts(), event: 'ledger.error', repo: 'unknown', harness: 'amp',
      reason: `amp plugin: ${reason} (plugin ${process.pid}, #${spills})` }
    mkdirSync(dir, { recursive: true, mode: 0o700 })
    writeFileSync(`${dir}/.${name}.tmp`, JSON.stringify(line) + '\n', { mode: 0o600 })
    renameSync(`${dir}/.${name}.tmp`, `${dir}/${name}.jsonl`)
  } catch (err) {
    counts.spill_failed++
    console.error(`livy: could not record "${reason}":`, err)
  }
}

// takeCounts hands the failure counts to one child; give puts them back if it never ran.
function takeCounts(): string[] {
  const args = Object.entries(counts).filter(([, n]) => n > 0).map(([k, n]) => `${k}=${n}`)
  for (const k of Object.keys(counts) as (keyof typeof counts)[]) counts[k] = 0
  return args
}
function give(args: string[]): void {
  for (const a of args) {
    const [k, n] = a.split('=') as [keyof typeof counts, string]
    counts[k] += Number(n)
  }
}

function drain(): void {
  while (running < IN_FLIGHT && queue.length > 0) {
    const job = queue.shift() as Job
    const carried = takeCounts()
    const args = ['amp', job.event, ...carried, ...(job.flush ? ['flush=throttled'] : [])]
    running++
    let done = false
    let timer: ReturnType<typeof setTimeout> | undefined
    const finish = (failure?: string) => {
      if (done) return
      done = true
      clearTimeout(timer)
      running--
      if (failure) {
        give(carried)
        spill(`livy amp ${job.event} did not run (${failure}); event not recorded`)
      }
      drain()
    }
    let child: ReturnType<typeof spawn>
    try {
      child = spawn(LIVY, args, { cwd: job.cwd ?? process.cwd(), stdio: ['pipe', 'ignore', 'ignore'], env: { ...process.env, LIVY_DIR: DATA } })
    } catch {
      finish('spawn threw')
      continue
    }
    timer = setTimeout(() => { child.kill('SIGKILL'); finish(`timed out after ${CHILD_MS / 1000} s`) }, CHILD_MS)
    child.on('error', (err: { code?: string }) => finish(err.code ?? 'spawn failed'))
    child.on('exit', (code, signal) => finish(code === 0 ? undefined : `exit ${code ?? signal}`))
    child.stdin?.on('error', () => {})
    child.stdin?.end(JSON.stringify(job.facts))
  }
}

function push(job: Job): void {
  if (queue.length >= MAX_QUEUE) {
    counts.dropped++
    return
  }
  queue.push(job)
  queueMicrotask(drain)
}

// enqueue sends a thread's event from its folder, or holds it until the folder is known. The
// event's own time goes with it, since a held event is written later. When too many threads
// wait, the one waiting longest gives up its events, which are counted as not recorded.
function enqueue(thread: string, event: string, facts: object, flush = false): void {
  const job = { event, facts: { ...facts, at: Date.now() }, flush }
  const cwd = root ?? folders.get(thread)
  if (cwd) return push({ ...job, cwd })
  if (!held.has(thread) && held.size >= THREADS) {
    const oldest = held.keys().next().value as string
    counts.no_folder += held.get(oldest)?.length ?? 0
    held.delete(oldest)
  }
  const waiting = held.get(thread) ?? []
  if (waiting.length >= HELD_PER_THREAD) {
    counts.no_folder++
    return
  }
  waiting.push(job)
  held.set(thread, waiting)
}

// learn records the folder a thread's first shell command ran in (its workdir), and sends what
// waited for it. Later commands may run elsewhere; the thread's folder stays the first one.
function learn(thread: string, dir: string | undefined): void {
  if (!dir || root || folders.has(thread)) return
  if (folders.size >= THREADS) folders.delete(folders.keys().next().value as string)
  folders.set(thread, dir)
  for (const job of held.get(thread) ?? []) push({ ...job, cwd: dir })
  held.delete(thread)
}

// upload starts an upload that outlives this plugin, and does not wait for it; throttled, except
// the last one before an orb pauses.
function upload(now = false): void {
  try {
    const child = spawn(LIVY, ['amp', 'flush', ...(now ? ['flush=now'] : [])], { detached: true, stdio: 'ignore', env: { ...process.env, LIVY_DIR: DATA } })
    child.on('error', (err: { code?: string }) => spill(`livy amp flush did not run (${err.code ?? 'spawn failed'})`))
    child.unref()
  } catch {
    spill('livy amp flush did not run (spawn threw)')
  }
}

// guard makes a handler return nothing at once, whatever happens inside it.
function guard<A extends unknown[]>(handler: (...args: A) => void): (...args: A) => undefined {
  return (...args: A) => {
    try {
      handler(...args)
    } catch {
      counts.handler_errors++
    }
    return undefined
  }
}

// skillFacts is what a completed skill call loaded: the name it asked for and the folder Amp says
// it loaded from, never the skill's text or its arguments. The folder is Amp's last such line, so
// a SKILL.md that writes one itself does not decide it.
function skillFacts(input: Record<string, unknown>, output: unknown): { name?: string; dir?: string } {
  const name = typeof input?.name === 'string' ? input.name : undefined
  const blocks = (output as { content?: unknown } | undefined)?.content
  let uri: string | undefined
  for (const b of Array.isArray(blocks) ? blocks : []) {
    const text = (b as { text?: unknown } | null)?.text
    if (typeof text !== 'string') continue
    for (const m of text.matchAll(SKILL_DIR)) uri = m[1]
  }
  let dir: string | undefined
  try {
    if (uri) dir = fileURLToPath(uri)
  } catch {
    dir = undefined
  }
  return { name, dir }
}

// within is p's answer, or null when it has none in time.
function within<T>(p: Promise<T>, ms: number): Promise<T | null> {
  return Promise.race([p, new Promise<null>((done) => setTimeout(() => done(null), ms))]).catch(() => null)
}

export default function (amp: PluginAPI) {
  inOrb ||= amp.system.executor?.kind === 'remote'
  try {
    const r = amp.system.workspaceRoot
    if (r) root = amp.helpers.filePathFromURI(r)
  } catch {
    counts.handler_errors++
  }
  try {
    mkdirSync(`${DATA}/amp-plugin`, { recursive: true, mode: 0o700 })
    writeFileSync(MARKER, ts() + '\n', { mode: 0o600 })
  } catch {
    spill('could not write the crash marker; a crash of this plugin will not be detected')
  }
  push({ event: 'loaded', facts: { pid: process.pid, template: TEMPLATE }, flush: true })

  amp.on('session.start', guard((e, ctx) => {
    // parentThreadID() rejects here ("no active thread"); the parent is kept if it ever answers.
    void within(ctx.thread.parentThreadID(), 2000).then((parent) =>
      enqueue(e.thread.id, 'session.start', { thread: { id: e.thread.id }, parentThreadID: parent ?? undefined }))
  }))
  amp.on('agent.start', guard((e) => {
    enqueue(e.thread.id, 'agent.start', { thread: { id: e.thread.id }, id: e.id, changesWorkflow: e.changesWorkflow })
  }))
  amp.on('tool.result', guard((e) => {
    const sh = amp.helpers.shellCommandFromToolCall(e)
    learn(e.thread.id, sh?.dir)
    const shell = sh && PR_CREATE.test(sh.command) ? { command: sh.command, dir: sh.dir } : undefined
    const out = e.output as { exitCode?: unknown } | undefined
    const exitCode = typeof out?.exitCode === 'number' ? out.exitCode : undefined
    const skill = e.tool === 'skill' && e.status === 'done' ? skillFacts(e.input, e.output) : undefined
    enqueue(e.thread.id, 'tool.result', { thread: { id: e.thread.id }, toolUseID: e.toolUseID, tool: e.tool, status: e.status, exitCode, shell, skill })
  }))
  amp.on('agent.end', guard((e) => {
    const messages = e.messages.map((m) => {
      const u = m.role === 'assistant' ? m.usage : undefined
      const usage = u && { model: u.model, inputTokens: u.inputTokens, outputTokens: u.outputTokens,
        cacheCreationInputTokens: u.cacheCreationInputTokens, cacheReadInputTokens: u.cacheReadInputTokens }
      return { role: m.role, id: m.id, usage }
    })
    enqueue(e.thread.id, 'agent.end', { thread: { id: e.thread.id }, id: e.id, status: e.status, messages }, true)
    clearTimeout(idle)
    idle = setTimeout(() => upload(inOrb), inOrb ? ORB_IDLE_MS : IDLE_MS)
    idle.unref?.()
  }))

  amp.onDispose(() => {
    clearTimeout(idle)
    // Children already started finish on their own; what is still queued is not recorded.
    const lost = queue.splice(0).length
    if (lost > 0) spill(`${lost} queued event(s) not recorded: Amp unloaded the plugin first`)
    for (const jobs of held.values()) counts.no_folder += jobs.length
    held.clear()
    const carried = takeCounts()
    if (carried.length > 0) spill(`failures not yet reported at unload: ${carried.join(', ')}`)
    upload()
    try {
      rmSync(MARKER, { force: true })
    } catch {
      counts.handler_errors++
    }
  })
}
